SELECT priority, COUNT(*) AS closed, COUNT(*) - COUNT(CASE WHEN closed_at IS NULL THEN 1 ELSE 0 END) AS not_closed
FROM support_tickets
GROUP BY priority;

SELECT accounts.name, accounts.created_at
FROM accounts
WHERE accounts.country = 'US' AND accounts.industry = 'media' AND accounts.created_at > '2024-05-16';
